using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RefineBounds {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 static List<Vector3> Clip(List<Vector3> src,float y,bool above){var dst=new List<Vector3>();if(src.Count==0)return dst;var a=src.Last();bool ain=above?a.y>=y:a.y<=y;foreach(var b in src){bool bin=above?b.y>=y:b.y<=y;if(ain!=bin)dst.Add(Vector3.LerpUnclamped(a,b,(y-a.y)/(b.y-a.y)));if(bin)dst.Add(b);a=b;ain=bin;}return dst;}
 static List<Bounds> Bands(Mesh m,BoxCollider old){var ranges=new[]{old.bounds.min.y};var bs=new List<Bounds>();var bounds=m.bounds;var cuts=new List<float>{bounds.min.y};cuts.AddRange(new[]{.12f,.40f,.8f,1.2f,1.8f,2.3f}.Where(y=>y>bounds.min.y+.02f&&y<bounds.max.y-.02f));cuts.Add(bounds.max.y);var v=m.vertices;var ix=m.triangles;for(int i=0;i<cuts.Count-1;i++){bool first=true;Bounds b=default;float lo=cuts[i],hi=cuts[i+1];for(int j=0;j<ix.Length;j+=3){if(Mathf.Max(v[ix[j]].y,Mathf.Max(v[ix[j+1]].y,v[ix[j+2]].y))<lo||Mathf.Min(v[ix[j]].y,Mathf.Min(v[ix[j+1]].y,v[ix[j+2]].y))>hi)continue;var poly=Clip(Clip(new List<Vector3>{v[ix[j]],v[ix[j+1]],v[ix[j+2]]},lo,true),hi,false);foreach(var p in poly){if(first){b=new Bounds(p,Vector3.zero);first=false;}else b.Encapsulate(p);}}if(!first){b.SetMinMax(new Vector3(b.min.x,lo,b.min.z),new Vector3(b.max.x,hi,b.max.z));bs.Add(b);}}return bs;}
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");var candidates=JArray.Parse(File.ReadAllText(H+"ghost_candidates.json")).Where(q=>(int)q["empty"]>3).ToDictionary(q=>(string)q["asset"]);var log=new List<object>();string original=SceneManager.GetActiveScene().path;var cache=new Dictionary<string,List<Bounds>>();try{foreach(string f in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Circular.unity");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();foreach(var t in ts){var mf=t.GetComponent<MeshFilter>();var old=t.GetComponent<BoxCollider>();if(!mf||!mf.sharedMesh||!old||!old.enabled||old.isTrigger||t.GetComponents<Collider>().Length!=1)continue;string asset=AssetDatabase.GetAssetPath(mf.sharedMesh);if(!candidates.ContainsKey(asset))continue;if(!cache.TryGetValue(asset,out var bands)){bands=Bands(mf.sharedMesh,old);cache[asset]=bands;}var record=new{floor=f,name=t.name,id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),asset,oldCenter=V(old.center),oldSize=V(old.size),bands=bands.Select(b=>new{center=V(b.center),size=V(b.size)})};for(int i=0;i<bands.Count;i++){var c=i==0?old:t.gameObject.AddComponent<BoxCollider>();c.center=bands[i].center;c.size=bands[i].size;c.sharedMaterial=old.sharedMaterial;c.isTrigger=false;PrefabUtility.RecordPrefabInstancePropertyModifications(c);}log.Add(record);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(H+"refined_colliders.json",JsonConvert.SerializeObject(log,Formatting.Indented));return new{models=cache.Count,objects=log.Count};}
}
